#include <Arduino.h>
#include <SPI.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <TFT_eSPI.h>

// Dane Twojej sieci Wi-Fi
const char* ssid = "NAZWA_TWOJEJ_SIECI_WIFI";
const char* password = "HASLO_TWOJEJ_SIECI_WIFI";

// Piny zasilania i anteny LilyGO T-Embed
#define PIN_POWER_EN  46
#define PIN_ANT_SW0   16
#define PIN_ANT_SW1   17

// Piny SPI i sygnałowe dla CC1101
#define CC1101_SPI_CLK  11
#define CC1101_SPI_MOSI 9
#define CC1101_SPI_MISO 10
#define CC1101_SPI_CS   8
#define CC1101_GDO0     13

TFT_eSPI tft = TFT_eSPI();

// Rejestry konfiguracyjne CC1101 dla wM-Bus 868.95MHz
const byte wmbus_cc1101_init[] = {
    {0x0B, 0x06}, {0x0D, 0x21}, {0x0E, 0x65}, {0x0F, 0x6A},
    {0x10, 0xF8}, {0x11, 0x83}, {0x12, 0x06}, {0x15, 0x40},
    {0x18, 0x18}, {0x19, 0x16}, {0x1A, 0x6C}, {0x21, 0x56}, {0x25, 0x00}
};

void writeRegister(byte reg, byte value) {
    digitalWrite(CC1101_SPI_CS, LOW);
    SPI.transfer(reg);
    SPI.transfer(value);
    digitalWrite(CC1101_SPI_CS, HIGH);
}

void sendStrobe(byte strobe) {
    digitalWrite(CC1101_SPI_CS, LOW);
    SPI.transfer(strobe);
    digitalWrite(CC1101_SPI_CS, HIGH);
}

void initCC1101() {
    sendStrobe(0x30); // Reset CC1101
    delay(10);
    for (int i = 0; i < sizeof(wmbus_cc1101_init) / 2; i++) {
        writeRegister(wmbus_cc1101_init[i], wmbus_cc1101_init[i]);
    }
    sendStrobe(0x34); // Uruchomienie trybu RX
}

// Funkcja rysująca interfejs na ekranie urządzenia
void updateDisplay(String status, String id = "-", String serial = "-", String odczyt = "-") {
    tft.fillScreen(TFT_BLACK);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.drawString("wM-Bus Online Sniffer", 10, 10, 4);

    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.drawString("Status: " + status, 10, 45, 2);

    tft.setTextColor(TFT_ORANGE, TFT_BLACK);
    tft.drawString("Meter ID: " + id, 10, 75, 2);
    tft.drawString("Serial: " + serial, 10, 100, 2);

    tft.setTextColor(TFT_CYAN, TFT_BLACK);
    tft.drawString("Odczyt: " + odczyt, 10, 130, 4);
}

// Funkcja wysyłająca ramkę HEX do wmbusmeters.org za pomocą API REST
void decodeTelegramOnline(String hexFrame) {
    if (WiFi.status() != WL_CONNECTED) {
        updateDisplay("Brak Wi-Fi!");
        return;
    }

    updateDisplay("Dekodowanie w chmurze...");
    HTTPClient http;
    // Główny punkt końcowy analizatora wmbusmeters
    http.begin("https://wmbusmeters.org"); 
    http.addHeader("Content-Type", "application/x-www-form-urlencoded");
    http.addHeader("Accept", "application/json"); // Prośba o odpowiedź w formacie JSON

    // Formatowanie danych formularza (parametr telegram oczekuje ciągu znaków HEX)
    String postData = "driver=auto&telegram=" + hexFrame; 
    int httpResponseCode = http.POST(postData);

    if (httpResponseCode == 200) {
        String response = http.getString();
        JsonDocument doc;
        DeserializationError error = deserializeJson(doc, response);

        if (!error) {
            // Wyciąganie zdekodowanych parametrów strukturalnych obiektu JSON
            String meterId = doc["id"].as<String>();
            String serial = doc["serial"].as<String>();
            String consumption = doc["total_m3"].as<String>() + " m3";

            if(consumption == "null m3") {
                consumption = doc["consumption_m3"].as<String>() + " m3";
            }

            updateDisplay("Odebrano!", meterId, serial, consumption);
        } else {
            updateDisplay("Błąd parsowania JSON");
        }
    } else {
        updateDisplay("Błąd HTTP: " + String(httpResponseCode));
    }
    http.end();
}

void setup() {
    Serial.begin(115200);

    // Inicjalizacja ekranu TFT
    tft.init();
    tft.setRotation(1); // Ustawienie poziome dla T-Embed
    updateDisplay("Uruchamianie...");

    // Konfiguracja linii zasilania i anteny LilyGO
    pinMode(PIN_POWER_EN, OUTPUT);
    pinMode(PIN_ANT_SW0, OUTPUT);
    pinMode(PIN_ANT_SW1, OUTPUT);
    digitalWrite(PIN_POWER_EN, HIGH);
    digitalWrite(PIN_ANT_SW0, HIGH);
    digitalWrite(PIN_ANT_SW1, LOW);
    delay(100);

    // Połączenie z siecią bezprzewodową Wi-Fi
    WiFi.begin(ssid, password);
    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        updateDisplay("Laczenie z Wi-Fi...");
    }
    updateDisplay("Połaczono! Oczekiwanie...");

    // Konfiguracja SPI oraz radia CC1101
    pinMode(CC1101_SPI_CS, OUTPUT);
    digitalWrite(CC1101_SPI_CS, HIGH);
    SPI.begin(CC1101_SPI_CLK, CC1101_SPI_MISO, CC1101_SPI_MOSI, CC1101_SPI_CS);
    pinMode(CC1101_GDO0, INPUT);

    initCC1101();
}

void loop() {
    // Nasłuchiwanie sygnału odebrania ramki radiowej (GDO0 przechodzi w stan HIGH)
    if (digitalRead(CC1101_GDO0) == HIGH) {
        digitalWrite(CC1101_SPI_CS, LOW);
        byte rxBytes = SPI.transfer(0x3B | 0x40); // Odczyt liczby bajtów w buforze FIFO
        digitalWrite(CC1101_SPI_CS, HIGH);

        if (rxBytes > 0 && rxBytes < 64) {
            String hexFrame = "";
            digitalWrite(CC1101_SPI_CS, LOW);
            SPI.transfer(0x3F | 0x40); // Seryjny odczyt bufora FIFO
            for (byte i = 0; i < rxBytes; i++) {
                byte b = SPI.transfer(0);
                if (b < 0x10) hexFrame += "0";
                hexFrame += String(b, HEX);
            }
            digitalWrite(CC1101_SPI_CS, HIGH);

            // Wyślij przechwycony pakiet HEX do zdalnego dekodera
            decodeTelegramOnline(hexFrame);
        }

        // Resetowanie stanu bufora CC1101 i powrót do ciągłego nasłuchiwania (RX)
        sendStrobe(0x36); // SIDLE
        sendStrobe(0x3A); // SFRX
        sendStrobe(0x34); // SRX
    }
    delay(1);
}
